        string[] deletedTypeViolations = productionFiles
            .Where(path => Regex.IsMatch(File.ReadAllText(path), @"\bRoadBuildSystem\b"))
            .OrderBy(path => path, StringComparer.Ordinal)
            .ToArray();

        Assert.IsEmpty(
